    a = [[start, end] for start, end in a if start < end]
    b = [[start, end] for start, end in b if start < end]

    if not a:
        return []
    if not b:
        return sorted(a)

    # Merge overlapping/touching intervals in b to simplify
    b.sort()
    b_merged = []
    for start, end in b:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Merge overlapping/touching intervals in a
    a.sort()
    a_merged = []
    for start, end in a:
        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Now subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_current = []
            for c_start, c_end in current:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    new_current.append([c_start, c_end])
                else:
                    # There is overlap, keep the parts that don't overlap
                    if c_start < b_start:
                        new_current.append([c_start, b_start])
                    if c_end > b_end:
                        new_current.append([b_end, c_end])
            current = new_current

        result.extend(current)

    # Merge any touching intervals and sort
    result.sort()
    final = []
    for start, end in result:
        if final and start <= final[-1][1]:
            final[-1][1] = max(final[-1][1], end)
        else:
            final.append([start, end])

    return final

